/// The category a Codec belongs to, as designated by the multicodec table
///
/// ```swift
/// let protocols = Codecs.codecs(tagged: .multiaddr)
/// ```
public enum CodecTag: String, CaseIterable, Sendable {
    case cid
    case encryption
    case filecoin
    case hash
    case holochain
    case ipld
    case key
    case libp2p
    case multiaddr
    case multiformat
    case multihash
    case multikey
    case multisig
    case namespace
    case nonce
    case serialization
    case shelter
    case softhash
    case transport
    case varsig
    case vlad
    case zeroxcert
}


/// How settled a Codec's entry in the multicodec table is
///
/// - Warning: A `draft` Codec's code is not guaranteed to be stable, and a
///   `deprecated` one shouldn't be written into new buffers. Both remain
///   decodable, since buffers written against them still exist.
public enum CodecStatus: String, CaseIterable, Sendable {
    case deprecated
    case draft
    case permanent
}
